<template><div class="vs-tabs" role="tablist" :aria-label="ariaLabel"><button v-for="item in items" :id="`${idPrefix}-tab-${item.value}`" :key="item.value" type="button" role="tab" :aria-selected="modelValue===item.value" :aria-controls="`${idPrefix}-panel-${item.value}`" :tabindex="modelValue===item.value?0:-1" @click="$emit('update:modelValue',item.value)" @keydown="move($event,item.value)">{{ item.label }}<span v-if="item.count!==undefined" class="vs-tabs__count">{{ item.count }}</span></button></div></template>
<script setup>const props=defineProps({items:{type:Array,required:true},modelValue:{type:String,required:true},ariaLabel:{type:String,default:'Các mục'},idPrefix:{type:String,default:'tabs'}});const emit=defineEmits(['update:modelValue']);function move(event,value){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const index=props.items.findIndex(item=>item.value===value);let next=index;if(event.key==='ArrowLeft')next=(index-1+props.items.length)%props.items.length;if(event.key==='ArrowRight')next=(index+1)%props.items.length;if(event.key==='Home')next=0;if(event.key==='End')next=props.items.length-1;emit('update:modelValue',props.items[next].value);queueMicrotask(()=>document.getElementById(`${props.idPrefix}-tab-${props.items[next].value}`)?.focus())}</script>
<style scoped>.vs-tabs{display:flex;gap:var(--space-1);padding:var(--space-1);border:1px solid var(--border-subtle);border-radius:var(--radius-control);background:var(--surface-subtle);overflow:auto}.vs-tabs button{min-height:var(--control-height-sm);display:inline-flex;align-items:center;gap:var(--space-2);padding-inline:var(--space-3);border-radius:var(--radius-control);color:var(--text-secondary);font-weight:700;white-space:nowrap}.vs-tabs button[aria-selected='true']{background:var(--surface-default);color:var(--text-primary);box-shadow:var(--shadow-xs)}.vs-tabs button:focus-visible{outline:3px solid color-mix(in srgb,var(--border-focus) 35%,transparent);outline-offset:1px}.vs-tabs__count{min-width:22px;padding:1px var(--space-1);border-radius:var(--radius-pill);background:var(--status-neutral-bg);color:var(--status-neutral-text);font-size:var(--type-caption-size)}</style>
